DROP TABLE IF EXISTS `anhhuanluyen`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `anhhuanluyen` (
  `id` int NOT NULL AUTO_INCREMENT,
  `scan_id` int DEFAULT NULL,
  `du_doan_id` int DEFAULT NULL,
  `doi_tuong_id` int DEFAULT NULL,
  `url_anh` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nhan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nguon_du_lieu` enum('yolo','gemini','admin') COLLATE utf8mb4_unicode_ci NOT NULL,
  `do_tin_cay` float DEFAULT NULL,
  `diem_chat_luong` int DEFAULT NULL,
  `trang_thai` enum('cho_duyet','da_duyet','tu_choi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cho_duyet',
  `nguoi_duyet_id` int DEFAULT NULL,
  `thoi_gian_tao` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `thoi_gian_duyet` datetime DEFAULT NULL,
  `ghi_chu` text COLLATE utf8mb4_unicode_ci,
  `thoi_gian_xoa` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `nguoi_duyet_id` (`nguoi_duyet_id`),
  KEY `ix_AnhHuanLuyen_doi_tuong_id` (`doi_tuong_id`),
  KEY `ix_AnhHuanLuyen_du_doan_id` (`du_doan_id`),
  KEY `ix_AnhHuanLuyen_nhan` (`nhan`),
