INSERT INTO `bandich` VALUES (56,27,2,'Baby','/ˈbeɪ.bi/','n','Em bé, trẻ sơ sinh: một đứa trẻ rất nhỏ, đặc biệt là đứa trẻ mới sinh','/api/tts/baby?lang=en','gemini',1,'2026-05-06 20:30:25',NULL),(57,18,2,'Child','/tʃaɪld/','n','Đứa trẻ: một người còn nhỏ, chưa trưởng thành.','/api/tts/Child?lang=en','gemini',1,'2026-05-06 20:46:57',NULL),(58,29,2,'Earbud','/ˈɪr.bʌd/','n','Tai nghe nhét tai: thiết bị âm thanh nhỏ gọn được đeo trực tiếp vào tai để nghe nhạc hoặc thực hiện cuộc gọi.','/api/tts/Earbud?lang=en','gemini',1,'2026-05-06 20:47:39',NULL),(61,1,2,'Laptop','/ˈlæp.tɑːp/','n','Máy tính xách tay: một loại máy tính cá nhân nhỏ gọn có thể mang đi và sử dụng ở nhiều nơi.','/api/tts/Laptop?lang=en','thu_cong',1,'2026-05-06 21:25:08',NULL),(66,38,2,'Man','/mæn/','n','Đàn ông: một người trưởng thành thuộc giới tính nam','/api/tts/Man?lang=en','gemini',1,'2026-05-06 22:16:07',NULL),(67,39,2,'Boy','/bɔɪ/','n','Cậu bé: một người nam trẻ tuổi chưa trưởng thành','/api/tts/Boy?lang=en','gemini',1,'2026-05-07 07:34:59',NULL),(69,22,2,'Watch','/wɑːtʃ/','n','Đồng hồ: thiết bị đeo tay hoặc mang theo người dùng để xem giờ.','/api/tts/watch?lang=en','gemini',1,'2026-05-07 07:35:31',NULL),(71,3,2,'Keyboard','/ˈkiːbɔːrd/','n','Bàn phím: một thiết bị nhập liệu có các phím để gõ chữ cái, số và ký hiệu vào máy tính hoặc các thiết bị điện tử khác.','/api/tts/keyboard?lang=en','thu_cong',1,'2026-05-11 07:39:33',NULL),(72,44,2,'Apple','/ˈæp.əl/','n','Quả táo: một loại trái cây tròn, thường có vỏ đỏ hoặc xanh, thịt trắng và ngọt','/api/tts/Apple?lang=en','thu_cong',1,'2026-05-11 19:12:39',NULL),(73,46,2,'Village','/ˈvɪl.ɪdʒ/','n','Làng: một khu dân cư nhỏ, thường ở nông thôn, nhỏ hơn thị trấn.','/api/tts/Village?lang=en','gemini',1,'2026-05-11 19:21:26',NULL),(74,47,2,'Tumbler','/ˈtʌm.blər/','n','Cốc giữ nhiệt: một loại cốc có thành đôi thường được dùng để giữ đồ uống nóng hoặc lạnh.','/api/tts/Tumbler?lang=en','gemini',1,'2026-05-12 07:20:53',NULL),(75,5,2,'Book','/bʊk/','n','Sách: một tậ