INSERT INTO `dudoanai` VALUES (58,288,'gemini','lipstick',1,'{\"object_code\": \"lipstick\", \"category\": \"Phụ kiện\", \"translations\": [{\"lang_code\": \"en\", \"word_name\": \"Lipstick\", \"phonetic\": \"/ˈlɪp.stɪk/\", \"part_of_speech\": \"n\", \"definition\": \"son môi: một sản phẩm mỹ phẩm dùng để tô màu và trang điểm cho môi.\", \"example_sentences\": [{\"en\": \"She chose a beautiful red lipstick.\", \"vi\": \"Cô ấy chọn một cây son môi màu đỏ tuyệt đẹp.\"}, {\"en\": \"This lipstick has a matte finish.\", \"vi\": \"Cây son môi này có kết thúc lì.\"}, {\"en\": \"I always keep a lipstick in my purse.\", \"vi\": \"Tôi luôn giữ một cây son môi trong ví của mình.\"}]}], \"source\": \"scan_image\", \"scan_image_url\": \"https://res.cloudinary.com/djsepqzzi/image/upload/v1779692317/object_scanner/scans/itstiascod14bbkkmjnx.jpg\"}','2026-05-25 06:58:39','da_duyet','chinh',NULL),(62,308,'gemini','bolster_pillow',1,'{\"object_code\": \"bolster_pillow\", \"category\": \"Nội thất\", \"translations\": [{\"lang_code\": \"en\", \"word_name\": \"Bolster pillow\", \"phonetic\": \"/ˈboʊl.stər ˌpɪl.oʊ/\", \"part_of_speech\": \"n\", \"definition\": \"gối ôm: một loại gối dài hình trụ, thường dùng để ôm khi ngủ hoặc tựa lưng.\", \"example_sentences\": [{\"en\": \"I sleep with a bolster pillow every night.\", \"vi\": \"Tôi ngủ với một chiếc gối ôm mỗi tối.\"}, {\"en\": \"The bolster pillow has a beautiful floral pattern.\", \"vi\": \"Chiếc gối ôm có hoa văn hoa rất đẹp.\"}, {\"en\": \"She uses a bolster pillow to support her back while reading.\", \"vi\": \"Cô ấy dùng gối ôm để tựa lưng khi đọc sách.\"}]}], \"source\": \"scan_image\", \"scan_image_url\": \"https://res.cloudinary.com/djsepqzzi/image/upload/v1779779933/object_scanner/scans/dliopdhsxo5n9wvagirj.jpg\"}','2026-05-26 07:18:54','tu_choi','chinh',NULL),(63,314,'gemini','earbud',1,'{\"object_code\": \"earbuds\", \"category\": \"Điện tử\", \"translations\": [{\"lang_code\": \"en\", \"word_name\": \"Earbuds\", \"phonetic\": \"/ˈɪər.bʌdz/\", \"part_of_speech\": \"n\", \"definition\": \"tai nghe không dây: thiết bị điện tử nhỏ gọn, không dây, dùng để đeo vào tai và nghe âm thanh từ điện thoại hoặc các thiết bị khác.\", \"example_sentences\": [{\"en\": \"I use my earbuds to listen to music.\", \"vi\": \"Tôi dùng tai nghe không dây của mình để nghe nhạc.\"}, {\"en\": \"These earbuds fit perfectly in my ears.\", \"vi\": \"Những chiếc tai nghe không dây này vừa vặn hoàn hảo trong tai tôi.\"}, {\"en\": \"Don\'t forget to charge your earbuds before the trip.\", \"vi\": \"Đừng quên sạc tai nghe không dây của bạn trước chuyến đi.\"}]}], \"source\": \"scan_image\", \"scan_image_url\": \"https://res.cloudinary.com/djsepqzzi/image/upload/v1779801704/object_scanner/scans/sluunqbf8qi3v35jbhjd.jpg\", \"ma_bi_danh\": \"earbuds\", \"ma_doi_tuong_chinh\": \"earbud\", \"doi_tuong_chinh_id\": 29}','2026-05-26 13:21:46','da_duyet','chinh',NULL);
