INSERT INTO `vidu` VALUES (118,56,'The baby smiled at his mother.','Em bé mỉm cười với mẹ của mình.','gemini'),(119,56,'She carried the sleeping baby in her arms.','Cô ấy bế em bé đang ngủ trong vòng tay.','gemini'),(120,56,'A baby learns to crawl before walking.','Em bé học bò trước khi biết đi.','gemini'),(121,57,'The child is smiling happily in the picture.','Đứa trẻ đang mỉm cười vui vẻ trong bức ảnh.','gemini'),(122,57,'Every child deserves a safe and loving home.','Mỗi đứa trẻ đều xứng đáng có một mái nhà an toàn và yêu thương.','gemini'),(123,57,'She read a bedtime story to her child.','Cô ấy đọc truyện trước khi ngủ cho con mình.','gemini'),(124,58,'She uses wireless earbuds for her daily commute.','Cô ấy dùng tai nghe không dây khi đi làm hằng ngày.','gemini'),(125,58,'The earbud fell out of his ear during the run.','Chiếc tai nghe nhét tai rơi khỏi tai anh ấy khi đang chạy.','gemini'),(126,58,'Many people prefer earbuds because they are small and portable.','Nhiều người thích tai nghe nhét tai vì chúng nhỏ gọn và dễ mang theo.','gemini'),(133,61,'I use my laptop for work every day.','Tôi dùng máy tính xách tay để làm việc mỗi ngày.','gemini'),(134,61,'She bought a new laptop for her studies.','Cô ấy mua một chiếc máy tính xách tay mới để học tập.','gemini'),(135,61,'The laptop has a long battery life.','Chiếc máy tính xách tay có thời lượng pin dài.','gemini'),(148,66,'The man is wearing a white shirt.','Người đàn ông đang mặc áo sơ mi trắng.','gemini'),(149,66,'He is a handsome young man.','Anh ấy là một chàng trai trẻ đẹp trai.','gemini'),(150,66,'The man has his hands in his pockets.','Người đàn ông đang đút tay vào túi.','gemini'),(151,67,'The boy is playing with his toys.','Cậu bé đang chơi với đồ chơi của mình.','gemini'),(152,67,'A little boy is smiling at the camera.','Một cậu bé đang mỉm cười trước máy ảnh.','gemini'),(153,67,'He is a very smart boy.','Cậu ấy là một cậu bé rất thông minh.','gemini'),(157,69,'She wears a silver watch every day.','Cô ấy đeo một chiếc đồng hồ bạc mỗi ngày.','gemini'),(158,69,'My new watch tells both the time and date.','Chiếc đồng hồ mới của tôi hiển thị cả giờ và ngày.','gemini'),(159,69,'He looked at his watch to check the time.','Anh ấy nhìn đồng hồ để xem giờ.','gemini'),(166,72,'I eat an apple every day.','Tôi thích ăn một quả táo mỗi ngày.','gemini'),(167,72,'The apple is red and shiny.','Quả táo rơi từ trên cây xuống.','gemini'),(168,72,'An apple a day keeps the doctor away.','Cô ấy gọt vỏ quả táo trước khi ăn.','gemini'),(169,73,'The village is located high in the mountains.','Anh ấy sống ở một ngôi làng nhỏ trên núi.','gemini'),(170,73,'Many small houses are part of this village.','Ngôi làng này nổi tiếng với những ngôi nhà cổ kính.','gemini'),(171,73,'Life in the village seems very peaceful.','Nhiều người dân đã rời làng để tìm việc làm ở thành phố.','gemini'),(172,74,'She filled her tumbler with iced coffee.','Cô ấy đổ đầy cà phê đá vào cốc giữ nhiệt của mình.','gemini'),(173,74,'The tumbler kept his water cold all day.','Cái cốc giữ nhiệt đã giữ nước của anh ấy lạnh suốt cả ngày.','gemini'),(174,74,'He accidentally dropped his favorite tumbler.','Anh ấy vô tình làm rơi chiếc cốc giữ nhiệt yêu thích của mình.','gemini'),(175,75,'I like to read a book before bed.','Tôi thích đọc sách trước khi ngủ.','gemini'),(176,75,'This book has many colorful pictures.','Cuốn sách này có rất nhiều hình ảnh đầy màu sắc.','gemini'),(177,75,'She bought a new book from the store.','Cô ấy đã mua một cuốn sách mới từ cửa hàng.','gemini'),(421,152,'A person is waiting at the bus stop.','Một người đang đợi ở trạm xe buýt.','thu_cong'),(422,152,'Every person has a different story.','Mỗi người đều có một câu chuyện khác nhau.','thu_cong'),(423,152,'The police asked the person for his name.','Cảnh sát hỏi người đó tên là gì.','thu_cong'),(424,153,'He rides his bicycle to school every morning.','Cậu ấy đạp xe đến trường mỗi sáng.','thu_cong'),(425,153,'My bicycle has a small basket in front.','Xe đạp của tôi có một cái giỏ nhỏ ở phía trước.','thu_cong'),(426,153,'She learned to ride a bicycle when she was six.','Cô ấy học đi xe đạp khi lên sáu tuổi.','thu_cong'),(427,154,'Their car is parked in front of the house.','Chiếc ô tô của họ đang đỗ trước nhà.','thu_cong'),(428,154,'My father drives a black car to work every day.','Bố tôi lái một chiếc ô tô màu đen đi làm mỗi ngày.','thu_cong'),(429,154,'We took a long trip by car last weekend.','Chúng tôi đã có một chuyến đi dài bằng ô tô vào cuối tuần trước.','thu_cong'),(430,155,'He bought a new motorcycle last month.','Anh ấy đã mua một chiếc xe máy mới vào tháng trước.','thu_cong'),(431,155,'She rides her motorcycle carefully in the rain.','Cô ấy lái xe máy cẩn thận khi trời mưa.','thu_cong'),(432,155,'The motorcycle is parked near the gate.','Chiếc xe máy được đỗ gần cổng.','thu_cong'),(433,156,'The airplane is flying above the clouds.','Máy bay đang bay phía trên những đám mây.','thu_cong'),(434,156,'We arrived at the airport just before the airplane took off.','Chúng tôi đến sân bay ngay trước khi máy bay cất cánh.','thu_cong'),(435,156,'She looked out the airplane window during the flight.','Cô ấy nhìn ra ngoài cửa sổ máy bay trong chuyến bay.','thu_cong'),(436,157,'I usually take the bus to school.','Tôi thường đi xe buýt đến trường.','thu_cong'),(437,157,'The bus was crowded this morning.','Xe buýt sáng nay rất đông.','thu_cong'),(438,157,'We waited ten minutes for the bus.','Chúng tôi đã đợi xe buýt mười phút.','thu_cong'),(439,158,'The train arrived at the station on time.','Tàu hỏa đã đến ga đúng giờ.','thu_cong'),(440,158,'We traveled across the country by train.','Chúng tôi đã đi khắp đất nước bằng tàu hỏa.','thu_cong'),(441,158,'She was reading a book while waiting for the train.','Cô ấy đang đọc sách trong lúc chờ tàu hỏa.','thu_cong'),(442,159,'The truck is carrying fresh vegetables.','Chiếc xe tải đang chở rau củ tươi.','thu_cong'),(443,159,'A large truck stopped in front of the warehouse.','